function readableText(raw){
  return raw.split(/\n\s*\n/).map(block=>{
    const lines=block.split("\n").map(x=>x.trim()).filter(Boolean);
    return lines.reduce((out,line)=>{
      if(!out)return line;
      if(out.endsWith("-") && /^[a-z]/.test(line))return out.slice(0,-1)+line;
      return out+" "+line;
    },"");
  }).filter(Boolean).join("\n\n");
}
const LAYOUT_PARAGRAPH="\uE001",LAYOUT_FOOTNOTE="\uE003";
function pageText(page,readingId=state.active){
  const hints=pdfLayout[readingId]?.[page.number]||{},paragraphs=new Set(hints.p||[]),footnotes=new Set(hints.f||[]);
  let sourceIndex=0;
  return page.text.split(/\n\s*\n/).map(block=>{
    const sourceLines=block.split("\n"),lines=[];
    sourceLines.forEach(line=>{if(line.trim())lines.push({text:line.trim(),index:sourceIndex});sourceIndex+=1;});
    return lines.reduce((out,line,position)=>{
      if(!position)return line.text;
      if(out.endsWith("-")&&/^[a-z]/.test(line.text))return out.slice(0,-1)+line.text;
      const divider=footnotes.has(line.index)?LAYOUT_FOOTNOTE:paragraphs.has(line.index)?LAYOUT_PARAGRAPH:" ";
      return out+divider+line.text;
    },"");
  }).filter(Boolean).join("\n\n");
}
function printedPages(reading,page){
  if(reading.id==="three-essays"){
    const found=[...page.text.matchAll(/(?:^|\n)\s*-\s*(\d{3})\s*-\s*(?=\n|$)/g)].map(m=>m[1]);
    return found.length?found:[String(page.number+122)];
  }
  if(reading.id==="webster"){
    if(page.number===11)return["299"];
    const start=page.number<=10?240+2*(page.number-1):300+2*(page.number-12);
    return page.number===1?[String(start)]:[String(start),String(start+1)];
  }
  return [];
}
function pageLabel(reading,page,compact=false){
  const printed=printedPages(reading,page);
  const physical=compact?`PDF p. ${page.number}`:`PDF PAGE ${page.number}`;
  if(!printed.length)return physical;
  const value=printed.length===1?printed[0]:`${printed[0]}–${printed.at(-1)}`;
  return `${physical} (${compact?"printed p.":"PRINTED PAGE"} ${value})`;
}

function buildTabs(){
  $("#readingTabs").innerHTML = readings.map((r,i)=>`<button class="reading-tab ${r.id===state.active?"active":""}" data-id="${r.id}"><b>${i+1}. ${r.title}</b><span>${r.author} · ${r.year} · ${r.pages.length} PDF pages</span></button>`).join("");
  $("#mdReading").innerHTML = readings.map(r=>`<option value="${r.id}">${r.title}</option>`).join("") + `<option value="all">三篇综合索引</option>`;
  $$(".reading-tab").forEach(b=>b.onclick=()=>{state.active=b.dataset.id; renderReading();});
}

function markedPage(reading,page){
  const text=pageText(page,reading.id);
  const pageAnns=anns(reading.id).filter(a=>a.page===page.number).sort((a,b)=>a.start-b.start);
  let html=inlineAssist?layeredTextHtml(text,reading.id,page.number,pageAnns):personalAnnotationHtml(text,pageAnns,connectionItems(reading.id).filter(c=>c.page===page.number));
  html=html.replace(/(^|\n)(-\s*\d{1,3}\s*-)(?=\n|$)/g,'$1<span class="print-page-number">$2</span>');
  html=html.replace(/[—-]{6,}/g,"");
  html=html.replace(/(\n\n)(—{4,}|-{8,})([\s\S]*)$/, '$1<span class="footnote-rule">$2</span><span class="footnote-text">$3</span>');
  if(!html.includes('footnote-text'))html=html.replace(/\n([1-9])\s+([\s\S]*?)(?=\n?<span class="print-page-number">)/,'\n<span class="footnote-rule"></span><span class="footnote-text"><sup class="footnote-index">$1</sup> $2</span>');
  const q=$("#searchInput").value.trim();
  if(q){ const safe=escapeHtml(q).replace(/[.*+?^${}()|[\]\\]/g,"\\$&"); html=html.replace(new RegExp(`(${safe})`,`gi`),'<span class="search-hit">$1</span>'); }
  return formatPageTypography(html,reading.id,page.number,page.text);
}

function formatPageTypography(html,readingId,pageNumber,rawText){
  const hints=pdfLayout[readingId]?.[pageNumber]||{};
  const rawLines=rawText.split("\n");
  (hints.h||[]).forEach(index=>{
    const title=escapeHtml((rawLines[index]||"").trim());
    if(title&&html.includes(title))html=html.replace(title,`<strong class="reading-heading${/^[IVXLC]{1,8}$/.test(rawLines[index].trim())?" roman-heading":""}">${title}</strong>`);
  });
  html=html.replace(/(^|\n)([IVXLC]{1,8})(?=\n|$)/g,'$1<strong class="reading-heading roman-heading">$2</strong>');
  html=html.replace(/(^|\n)([A-Z][A-Z0-9 &amp;,'’():.\-]{8,})(?=\n|$)/g,'$1<strong class="reading-heading">$2</strong>');
  html=html.replace(/([A-Za-z)”’.'”])([1-9])(?=\s+(?:[A-Z]|Cf\.))/g,'$1<sup class="footnote-index">$2</sup>');
  html=html.replace(/(<span class="footnote-text">)([1-9])\s+/g,'$1<sup class="footnote-index">$2</sup> ');
  html=html.replace(/\n([1-9])\s+(?=[A-Z])/g,'\n<sup class="footnote-index">$1</sup> ');
  html=html.replaceAll(LAYOUT_PARAGRAPH,'<span class="paragraph-gap"> </span>');
  if(html.includes(LAYOUT_FOOTNOTE)){
    html=html.replace(LAYOUT_FOOTNOTE,'<span class="footnote-rule pdf-derived-rule"> </span><span class="footnote-text pdf-derived-footnote">');
    html=html.replace(/(<span class="print-page-number">)/,'</span>$1');
    if(!html.includes('</span><span class="print-page-number">'))html+='</span>';
  }
  html=html.replace(/<span class="footnote-text pdf-derived-footnote">([\s\S]*?)<\/span>/g,(whole,content)=>{
    const numbered=content.replace(/(^|\s)([1-9]\d*|[a-d])[.)]?\s+(?=(?:<[^>]+>)*[A-Z‘“\[])/g,'$1\uE004$2 ');
    if(!numbered.includes('\uE004'))return whole;
    const pieces=numbered.split('\uE004'),prefix=pieces.shift();
    const entries=pieces.map(piece=>{const match=piece.match(/^([1-9]\d*|[a-d])\s+([\s\S]*)$/);return match?`<span class="footnote-entry"><sup class="footnote-index">${match[1]}</sup> ${match[2]}</span>`:piece;}).join("");
    return `<span class="footnote-text pdf-derived-footnote">${prefix}${entries}</span>`;
  });
  html=html.replace(/([.!?][”’"']?(?:<\/(?:mark|span)>)*)\n(?=(?:<(?:mark|span)[^>]*>)*[A-Z“‘])/g,'$1<span class="paragraph-gap">\n</span>');
  return html.replace(/\n/g," ");
}

