function inferredArgumentHighlights(text){const rules=[['concession',/\b(although|however|it is true|even so|nevertheless)\b/i],['progression',/\b(therefore|consequently|thus|we are driven to conclude|it follows)\b/i],['hypothesis',/\b(perhaps|may suppose|may be suggested|hypothesis|presume)\b/i],['counter',/\b(on the contrary|cannot|objection|fails? to|not true)\b/i],['definition',/\b(is called|we shall call|by .* mean|the term|defined as)\b/i],['support',/\b(we find|observation|evidence|demonstrat|showed? that)\b/i]];const found=[];for(const sentence of text.split(/(?<=[.!?])\s+/)){const clean=sentence.trim();if(clean.length<45||clean.length>360)continue;const rule=rules.find(([,rx])=>rx.test(clean));if(rule&&!found.some(x=>x.type===rule[0]))found.push({type:rule[0],text:clean});if(found.length===2)break;}return found;}
