function addAnnotation(style){
  if(editingAnnotationId){const item=anns(state.active).find(a=>a.id===editingAnnotationId);if(item){item.style=style;persist();editingAnnotationId="";hideSelectionTools();renderReading();toast(`已改为${styleLabels[style]}`);return;}}
  const sel=window.getSelection(); if(!sel || sel.isCollapsed)return toast("请先在原文中选择一段文字");
  const range=sel.getRangeAt(0), startEl=range.startContainer.parentElement?.closest(".page-text"), endEl=range.endContainer.parentElement?.closest(".page-text");
  if(!startEl || startEl!==endEl)return toast("一次标注请不要跨 PDF 页");
  const page=Number(startEl.closest(".pdf-page").dataset.page), text=pageText(current().pages[page-1],state.active);
  const before=document.createRange(); before.selectNodeContents(startEl); before.setEnd(range.startContainer,range.startOffset);
  const start=before.toString().length, quote=range.toString(), end=start+quote.length;
  if(!quote.trim())return;
  state.annotations[state.active]=[...anns(state.active),{id:Date.now().toString(36),page,start,end,quote,style,note:"",created:new Date().toISOString()}];
  persist(); sel.removeAllRanges(); hideSelectionTools(); renderReading(); toast(`已标记为${styleLabels[style]}`);
}

