function drawLinks(){
  const c=$("#linkCanvas"),a=$("#conceptCanvas"),dpr=devicePixelRatio||1;c.width=a.clientWidth*dpr;c.height=a.clientHeight*dpr;const ctx=c.getContext("2d");ctx.scale(dpr,dpr);ctx.strokeStyle="#a9aaa2";ctx.lineWidth=1.4;links.forEach(([x,y])=>{const A=a.querySelector(`[data-id="${x}"]`),B=a.querySelector(`[data-id="${y}"]`);if(!A||!B)return;ctx.beginPath();ctx.moveTo(A.offsetLeft+A.offsetWidth/2,A.offsetTop+A.offsetHeight/2);ctx.lineTo(B.offsetLeft+B.offsetWidth/2,B.offsetTop+B.offsetHeight/2);ctx.stroke();});
}
