function editNode(node){const label=prompt("概念名称",node.label);if(label===null||!label.trim())return;const desc=prompt("说明",node.desc||"");if(desc===null)return;const edited={...node,label:label.trim(),desc:desc.trim(),type:baseNodes.some(n=>n.id===node.id)?node.type:"custom"};state.customNodes=state.customNodes.filter(n=>n.id!==node.id);state.customNodes.push(edited);persist();renderCanvas();}
