 {id:"pe-mc-1",source:"Educational Psychology 8e · Ch. 1",concept:"Psy&Edu · Foundations",question:"Which statement best defines educational psychology?",options:["The study of school administration only","The branch of psychology concerned with teaching and learning in educational settings","The measurement of intelligence without classroom application","The history of educational institutions"],answer:1,explanations:["Administration is not the defining focus.","Correct. The field specializes in understanding teaching and learning in educational settings.","Assessment is one topic, not the whole field.","History informs the field but does not define it."]},
 {id:"pe-fill-1",type:"fill",source:"Educational Psychology 8e · Ch. 1",concept:"Psy&Edu · Foundations",question:"Psychology is the scientific study of behavior and mental ______.",answer:"processes",aliases:["process"],explanation:"The definition pairs observable behavior with mental processes."},
 {id:"pe-mc-2",source:"Educational Psychology 8e · Ch. 2",concept:"Psy&Edu · Development",question:"In Piaget's theory, what process changes an existing schema to fit new information?",options:["Assimilation","Accommodation","Conservation","Equilibration"],answer:1,explanations:["Assimilation uses an existing schema.","Correct. Accommodation modifies the schema.","Conservation concerns stable quantity despite perceptual change.","Equilibration regulates movement toward cognitive balance."]},
 {id:"pe-fill-2",type:"fill",source:"Educational Psychology 8e · Ch. 2",concept:"Psy&Edu · Development",question:"Vygotsky's range between independent performance and performance with guidance is the zone of proximal ______.",answer:"development",aliases:["zpd"],explanation:"The zone of proximal development identifies tasks possible with appropriate assistance."},
 {id:"pe-mc-3",source:"Educational Psychology 8e · Ch. 3",concept:"Psy&Edu · Social Context",question:"Which Bronfenbrenner system contains direct settings such as family, school, and peers?",options:["Microsystem","Exosystem","Macrosystem","Chronosystem"],answer:0,explanations:["Correct. The learner directly participates in the microsystem.","The exosystem affects the learner indirectly.","The macrosystem includes broad cultural patterns.","The chronosystem concerns change across time."]},
 {id:"pe-fill-3",type:"fill",source:"Educational Psychology 8e · Ch. 3",concept:"Psy&Edu · Social Context",question:"Erikson described adolescence as identity versus role ______.",answer:"confusion",aliases:["role confusion"],explanation:"Resolving identity versus role confusion supports a coherent sense of self."},
 {id:"pe-mc-4",source:"Educational Psychology 8e · Ch. 4",concept:"Psy&Edu · Individual Variations",question:"What is the most evidence-aligned conclusion about learning styles?",options:["Always match instruction to a declared style","Learning-style labels reliably predict achievement","Rigid matching to learning-style categories is not supported","Each student has one stable way to learn"],answer:2,explanations:["Rigid matching is not supported.","The labels do not reliably predict achievement.","Correct. Use flexible, task-appropriate strategies.","Strategies vary by task and context."]},
 {id:"pe-fill-4",type:"fill",source:"Educational Psychology 8e · Ch. 4",concept:"Psy&Edu · Individual Variations",question:"A characteristic emotional and behavioral response style is called ______.",answer:"temperament",aliases:[],explanation:"Temperament refers to relatively enduring response patterns."},
 {id:"pe-mc-5",source:"Educational Psychology 8e · Ch. 5",concept:"Psy&Edu · Diversity",question:"Culturally relevant teaching primarily aims to:",options:["Ignore cultural differences","Use students' cultural knowledge and experiences as learning resources","Give every student identical examples","Replace academic goals with cultural activities"],answer:1,explanations:["Ignoring difference can reproduce inequity.","Correct. Culture becomes an instructional asset.","Equity does not require identical examples.","Rigor and cultural relevance are compatible."]},
 {id:"pe-fill-5",type:"fill",source:"Educational Psychology 8e · Ch. 5",concept:"Psy&Edu · Diversity",question:"The abbreviation SES stands for socioeconomic ______.",answer:"status",aliases:["socioeconomic status"],explanation:"SES commonly combines education, occupation, and income indicators."},
 {id:"pe-mc-7",source:"Educational Psychology 8e · Ch. 7",concept:"Psy&Edu · Learning",question:"Which consequence increases behavior by removing an aversive stimulus?",options:["Positive punishment","Negative punishment","Positive reinforcement","Negative reinforcement"],answer:3,explanations:["This adds an aversive consequence.","This removes a desirable stimulus.","This adds a desirable consequence.","Correct. Negative reinforcement strengthens behavior through removal."]},
 {id:"pe-fill-7",type:"fill",source:"Educational Psychology 8e · Ch. 7",concept:"Psy&Edu · Learning",question:"Learning by observing and imitating a model is called ______ learning.",answer:"observational",aliases:["modeling","modelling"],explanation:"Bandura made observational learning central to social cognitive theory."},
 {id:"pe-mc-8",source:"Educational Psychology 8e · Ch. 8",concept:"Psy&Edu · Memory",question:"Which strategy most directly improves long-term retention?",options:["Passive rereading only","Retrieval practice spaced across time","One late massed study session","Avoiding feedback"],answer:1,explanations:["Familiarity is not durable retrieval.","Correct. Spaced retrieval strengthens access and reveals gaps.","Massed practice is vulnerable to forgetting.","Feedback supports correction."]},
 {id:"pe-fill-8",type:"fill",source:"Educational Psychology 8e · Ch. 8",concept:"Psy&Edu · Memory",question:"Thinking about and regulating one's own thinking is called ______.",answer:"metacognition",aliases:["meta-cognition"],explanation:"Metacognition includes planning, monitoring, and evaluating cognition."},
 {id:"pe-mc-10",source:"Educational Psychology 8e · Ch. 10",concept:"Psy&Edu · Constructivism",question:"What is scaffolding?",options:["Permanent task simplification","Temporary support withdrawn as competence grows","Giving answers before an attempt","Assessment without instruction"],answer:1,explanations:["The goal is independent performance.","Correct. Support is contingent and gradually faded.","Scaffolding supports rather than replaces thinking.","Assessment alone is not scaffolding."]},
 {id:"pe-fill-13",type:"fill",source:"Educational Psychology 8e · Ch. 13",concept:"Psy&Edu · Motivation",question:"A learner's belief about capability to succeed at a specific task is self-______.",answer:"efficacy",aliases:["self-efficacy"],explanation:"Self-efficacy influences effort, persistence, and strategy use."},
 {id:"pe-mc-15",source:"Educational Psychology 8e · Ch. 15",concept:"Psy&Edu · Assessment",question:"A criterion-referenced score is interpreted against:",options:["A norm group","A defined standard or learning objective","A personality profile","A grading curve"],answer:1,explanations:["That is norm-referenced.","Correct. Criterion referencing asks whether a defined standard was met.","Personality is unrelated.","A curve is norm-oriented."]},
 {id:"pe-fill-15",type:"fill",source:"Educational Psychology 8e · Ch. 15",concept:"Psy&Edu · Assessment",question:"The consistency of scores across occasions, forms, or raters is called ______.",answer:"reliability",aliases:[],explanation:"Reliability concerns consistency; validity concerns supported interpretation."}
