const allQuestions=()=>[...builtInQuestions,...state.questions.filter(q=>q?.question?.trim()&&(q.type==="fill"||q.options?.some(option=>String(option).trim())))];
let quizFilter="All";
function renderQuiz(){const questions=allQuestions(),concepts=["All",...new Set(questions.map(q=>q.concept))];if(!concepts.includes(quizFilter))quizFilter="All";$("#quizFilters").innerHTML=concepts.map(c=>`<button class="${c===quizFilter?"active":""}" data-filter="${escapeHtml(c)}">${escapeHtml(c)}</button>`).join("");$$('[data-filter]').forEach(b=>b.onclick=()=>{quizFilter=b.dataset.filter;renderQuiz();});const shown=questions.filter(q=>quizFilter==="All"||q.concept===quizFilter);$("#quizList").innerHTML=shown.map(quizCard).join("")||'<div class="empty-quiz">No questions yet. Import a question set to begin.</div>';wireQuiz();updateQuizScore();}
function normalizedAnswer(value){return String(value??"").trim().toLowerCase().replace(/[._-]+/g," ").replace(/\s+/g," ");}
function fillIsCorrect(q,value){const accepted=[q.answer,...(q.aliases||[])].map(normalizedAnswer);return accepted.includes(normalizedAnswer(value));}
function quizCard(q){if(q.type==="fill")return fillQuizCard(q);const chosen=state.answers[q.id],answered=Number.isInteger(chosen),correct=chosen===q.answer;return `<article class="quiz-card"><div class="knowledge-row"><span>MCQ</span><div><b>${escapeHtml(q.concept)}</b><small>${escapeHtml(q.source||"ChatGPT import")}</small></div></div><div class="question-body always-open"><h2>${escapeHtml(q.question)}</h2><div class="answer-options">${q.options.map((o,i)=>`<button data-question="${q.id}" data-choice="${i}" class="${answered?(i===q.answer?"correct":i===chosen?"wrong":"dimmed"):""}" ${answered?"disabled":""}><i>${String.fromCharCode(65+i)}</i>${escapeHtml(o)}</button>`).join("")}</div>${answered?`<div class="result ${correct?"pass":"retry"}"><b>${correct?"✓ Correct":"✕ Try again"}</b><span>Answer: ${String.fromCharCode(65+q.answer)}</span></div><div class="explanations"><h3>Why?</h3>${q.options.map((o,i)=>`<p class="${i===q.answer?"is-correct":""}"><b>${String.fromCharCode(65+i)} · ${i===q.answer?"Correct":"Not correct"}</b>${escapeHtml(q.explanations[i]||"No explanation yet.")}</p>`).join("")}</div><button class="try-again" data-retry="${q.id}">Try again</button>`:""}</div></article>`;}
function fillQuizCard(q){const chosen=state.answers[q.id],answered=typeof chosen==="string",correct=answered&&fillIsCorrect(q,chosen);return`<article class="quiz-card fill-card"><div class="knowledge-row"><span>FILL</span><div><b>${escapeHtml(q.concept)}</b><small>${escapeHtml(q.source)}</small></div></div><div class="question-body always-open"><h2>${escapeHtml(q.question)}</h2>${answered?`<div class="fill-answer ${correct?"correct":"wrong"}"><span>Your answer: <b>${escapeHtml(chosen)}</b></span><span>Correct answer: <b>${escapeHtml(q.answer)}</b></span></div><div class="result ${correct?"pass":"retry"}"><b>${correct?"✓ Correct":"✕ Not quite"}</b></div><div class="explanations"><h3>Why?</h3><p class="is-correct">${escapeHtml(q.explanation)}</p></div><button class="try-again" data-retry="${q.id}">Try again</button>`:`<div class="fill-entry"><input data-fill-input="${q.id}" type="text" autocomplete="off" placeholder="Type the missing word…"><button data-fill-submit="${q.id}" class="primary">Check answer</button></div>`}</div></article>`;}
function wireQuiz(){$$('[data-question]').forEach(b=>b.onclick=()=>{state.answers[b.dataset.question]=Number(b.dataset.choice);persist();renderQuiz();});$$('[data-fill-submit]').forEach(b=>b.onclick=()=>{const input=$(`[data-fill-input="${b.dataset.fillSubmit}"]`);if(!input?.value.trim())return toast("Type an answer first");state.answers[b.dataset.fillSubmit]=input.value.trim();persist();renderQuiz();});$$('[data-fill-input]').forEach(i=>i.onkeydown=e=>{if(e.key==="Enter")$(`[data-fill-submit="${i.dataset.fillInput}"]`)?.click();});$$('[data-retry]').forEach(b=>b.onclick=()=>{delete state.answers[b.dataset.retry];persist();renderQuiz();});}
function updateQuizScore(){const qs=allQuestions(),answered=qs.filter(q=>Number.isInteger(state.answers[q.id])||typeof state.answers[q.id]==="string"),correct=answered.filter(q=>q.type==="fill"?fillIsCorrect(q,state.answers[q.id]):state.answers[q.id]===q.answer).length;$("#quizScore").textContent=`${correct} / ${answered.length}`;}
function normalizeQuestion(q){if(q.type==="fill"){if(!q.concept||!q.question||typeof q.answer!=="string"||!q.answer.trim())throw new Error("填空题需要 concept、question 和文字 answer");return{id:q.id||`import-${Date.now()}-${Math.random()}`,type:"fill",source:q.source||"ChatGPT import",concept:String(q.concept),question:String(q.question),answer:q.answer.trim(),aliases:(q.aliases||[]).map(String),explanation:String(q.explanation||"")};}if(!q.concept||!q.question||!Array.isArray(q.options)||q.options.length<2||!Number.isInteger(q.answer)||q.answer<0||q.answer>=q.options.length)throw new Error("选择题需要 concept、question、至少两个 options 和数字 answer");return{id:q.id||`import-${Date.now()}-${Math.random()}`,source:q.source||"ChatGPT import",concept:String(q.concept),question:String(q.question),options:q.options.map(String),answer:q.answer,explanations:(q.explanations||[]).map(String)};}
function parseQuestions(raw){const text=raw.trim();if(!text)return[];if(text.startsWith("["))return JSON.parse(text).map(normalizeQuestion);return text.split(/\n\s*\n(?=知识点[:：])/).map((block,idx)=>{const lines=block.split("\n").map(s=>s.trim()).filter(Boolean),get=key=>lines.find(x=>x.match(new RegExp(`^${key}[:：]`)))?.replace(new RegExp(`^${key}[:：]\\s*`),"")||"",opts=lines.filter(x=>/^[A-D][.、:：]\s*/.test(x)).map(x=>x.replace(/^[A-D][.、:：]\s*/,"")),letter=get("答案").toUpperCase().charCodeAt(0)-65;return normalizeQuestion({id:`import-${Date.now()}-${idx}`,concept:get("知识点"),question:get("题目"),options:opts,answer:letter,explanations:opts.map((_,i)=>get(`解析${String.fromCharCode(65+i)}`)),source:"ChatGPT 导入"});});}

function thoughtCollection(id){const r=readings.find(x=>x.id===id),items=anns(id).filter(a=>a.style==="think");return items.map(a=>`### ${r.title} · ${pageLabel(r,r.pages[a.page-1],true)}\n> ${a.quote.replace(/\n/g," ")}\n\n${a.note||"_待补充思考_"}`).join("\n\n");}
function courseConnectionsMarkdown(id){return connectionItems(id).map(c=>`### ${c.stance==="support"?"Supporting connection":c.stance==="counter"?"Counterargument":"Qualification"} · PDF p. ${c.page}\n> ${c.text}\n\n- **Lecture:** [[Group Dynamics Lecture - Freud Unit]] (${c.ref})\n- **Connection:** ${c.note}`).join("\n\n")||"_No course connections yet._";}
function markdownFor(id){
  if(id==="all") return `---\ntype: map-of-content\ncourse: Group Dynamics\nweek: 1\ntags: [psychoanalysis, Freud, critique]\n---\n# Freud Unit（弗洛伊德单元）· Knowledge Map（知识地图）\n\n## Readings（阅读）\n${readings.map(r=>`- [[${r.title}]] — ${r.author} (${r.year})`).join("\n")}\n\n## Core Connections（核心连接）\n- [[Psychical Conflict（心理冲突）]] → [[Defence（防御）]] → [[Symptom Formation（症状形成）]]\n- [[Component Instincts（部分驱力）]] → [[Infantile Sexuality（儿童性欲）]] → [[Genital Organization（生殖器组织）]]\n- [[Normal–Pathological Continuity（正常—病理连续体）]]\n- [[Evidence and Falsifiability（证据与可证伪性）]] ← Webster's methodological critique（方法论批评）\n\n## Quote & Reflection Collection（金句／思考合集）\n${readings.map(r=>thoughtCollection(r.id)).filter(Boolean).join("\n\n")||"_尚无紫色金句／思考标注_"}\n\n## Comparative Questions（对照问题）\n${conflicts.map(c=>`- **${c.title}**：${c.text}`).join("\n")}\n`;
  const r=readings.find(x=>x.id===id), s=summaries[id], notes=anns(id);
  return `---\ntype: source\nauthor: ${r.author}\nyear: ${r.year}\ncourse: Group Dynamics\nstatus: ${state.read[id]?"已读":"阅读中"}\ntags: [psychoanalysis, group-dynamics]\n---\n# ${r.title}\n\n> [!info] Source（来源）\n> ${r.author} (${r.year}). PDF: ${r.fileName}\n\n## Three Core Claims（三个核心观点）\n${s.points.map((p,i)=>`${i+1}. ${p}`).join("\n")}\n\n## Evidence（论据类型）\n${s.evidence}\n\n## Quote & Reflection Collection（金句／思考合集）\n${thoughtCollection(id)||"_尚无紫色金句／思考标注_"}\n\n## My Annotations（我的批注）\n${notes.length?notes.map(a=>`### ${pageLabel(r,r.pages[a.page-1],true)}\n> ${a.quote.replace(/\n/g," ")}\n\n${a.note||"_待补充想法_"}`).join("\n\n"):"_尚无批注_"}\n\n## Linked Concepts（可连接概念）\n- [[Psychical Conflict（心理冲突）]]\n- [[Defence（防御）]]\n- [[Symptom Formation（症状形成）]]\n- [[Infantile Sexuality（儿童性欲）]]\n- [[Normal–Pathological Continuity（正常—病理连续体）]]\n- [[Evidence and Falsifiability（证据与可证伪性）]]\n\n## Related Readings（相关阅读）\n${readings.filter(x=>x.id!==id).map(x=>`- [[${x.title}]]`).join("\n")}\n`;
}
function markdownWithCourse(id){const base=markdownFor(id).replace("week: 1","week: 2").replace("tags: [psychoanalysis, Freud, critique]","tags: [psychoanalysis, Freud, critique, reading-response]").replace("tags: [psychoanalysis, group-dynamics]","tags: [psychoanalysis, group-dynamics, reading-response]");const requirements=`## Reading Response Requirements\n- Write 2–4 pages.\n- Critically evaluate key concepts or arguments.\n- Apply the reading to a real-world experience.\n- Build a clear, coherent argument.\n- Use at least three textual examples for the proficient level; the exceptional rubric asks for more than three.\n\n`;const connections=id==="all"?readings.map(r=>`### [[${r.title}]]\n${courseConnectionsMarkdown(r.id)}`).join("\n\n"):courseConnectionsMarkdown(id);return base.replace("## Quote & Reflection Collection（金句／思考合集）",`${requirements}## Lecture & Syllabus Connections\n${connections}\n\n## Quote & Reflection Collection（金句／思考合集）`);}
function updateMd(){ $("#mdPreview").textContent=markdownWithCourse($("#mdReading").value); }
function downloadMd(){const id=$("#mdReading").value,name=id==="all"?"Freud 单元 - 知识地图":readings.find(r=>r.id===id).title;const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([markdownWithCourse(id)],{type:"text/markdown"}));a.download=name.replace(/[/:]/g,"-")+".md";a.click();URL.revokeObjectURL(a.href);}
