function formattedRuns(block){
  if(!block.runs?.length)return escapeHtml(block.text||"");
  return block.runs.map(run=>{let value=escapeHtml(run.text);if(run.bold)value=`<strong>${value}</strong>`;if(run.italic)value=`<em>${value}</em>`;if(run.underline)value=`<u>${value}</u>`;if(run.highlight)value=`<mark>${value}</mark>`;return value;}).join("");
}
function renderNoteBlocks(blocks){
  const counters=[];
  return blocks.map((block,index)=>{
    const level=Math.min(5,Math.max(0,block.level||0));
    if(block.numbered){counters[level]=(counters[level]||0)+1;counters.length=level+1;}
    const marker=block.numbered?[`${counters[level]}.`,`${String.fromCharCode(96+counters[level])}.`,`${romanNumber(counters[level])}.`,`•`,`–`,`◦`][level]:"";
    const isHeading=!block.numbered&&(block.bold||index===0||/^(Syllabus|Freud|Psychoanalysis|COURSE REQUIREMENTS)[:：]?$/.test(block.text||""));
    const text=block.text?`<div class="note-copy ${isHeading?"note-heading":""}" style="--note-level:${level}">${marker?`<span class="note-marker">${marker}</span>`:""}<span>${formattedRuns(block)}</span></div>`:"";
    const images=(block.images||[]).map((src,i)=>`<figure class="original-note-image" style="--note-level:${level}"><img src="${src}" alt="Original lecture-note image ${i+1}" loading="lazy"></figure>`).join("");
    return text+images;
  }).join("");
}
function romanNumber(value){const map=[[10,"x"],[9,"ix"],[5,"v"],[4,"iv"],[1,"i"]];let n=value,out="";for(const [amount,label] of map)while(n>=amount){out+=label;n-=amount;}return out;}
function renderLectureArchive(){
  const notes=lectureArchiveData.notes,slides=lectureArchiveData.slides;
  $("#lectureIndex").innerHTML=notes.map((x,i)=>`<button data-lecture-id="${x.id}" class="${i===0?"active":""}"><b>${x.date}</b><small>${x.label} · ${escapeHtml(x.title)}</small></button>`).join("");
  $("#coverageLabel").textContent=`Slides 3–${lectureArchiveData.coveredThrough} · covered so far`;
  $("#lectureBook").innerHTML=notes.map(x=>{
    const matched=slides.filter(s=>x.slides.includes(s.number)),unmapped=x.blocks.filter(b=>b.slide==null);
    const units=matched.map(s=>{const related=x.blocks.filter(b=>b.slide===s.number);return `<article class="slide-note-unit" data-slide-unit="${s.number}"><div class="unit-slide"><div class="slide-number">SLIDE ${s.number}</div><img src="${s.image}" alt="Slide ${s.number}: ${escapeHtml(s.title)}" loading="lazy"></div><div class="unit-notes"><div class="column-label">MY NOTES · SLIDE ${s.number}</div>${related.length?renderNoteBlocks(related):`<p class="no-direct-note">No direct note on this slide.</p>`}${s.transcript?`<div class="teacher-transcript"><b>Professor transcript</b><p>${escapeHtml(s.transcript)}</p></div>`:""}</div></article>`;}).join("");
    const freeNotes=!matched.length||unmapped.length?`<article class="slide-note-unit note-only-unit"><div class="unit-slide"><div class="no-slide"><b>${matched.length?"Notes without a single-slide match":"Course notes"}</b><p>${matched.length?"Kept separately rather than forcing an inaccurate alignment.":"This class focused on the course frame and syllabus."}</p></div></div><div class="unit-notes"><div class="column-label">MY NOTES</div>${renderNoteBlocks(matched.length?unmapped:x.blocks)}</div></article>`:"";
    const extra=localTranscript.text&&x.id===notes.at(-1).id?`<article class="slide-note-unit note-only-unit"><div class="unit-slide"><div class="no-slide"><b>Additional transcript</b></div></div><div class="unit-notes"><div class="teacher-transcript local-transcript"><b>${escapeHtml(localTranscript.name)}</b><p>${escapeHtml(localTranscript.text)}</p></div></div></article>`:"";
    return `<section class="lecture-entry lecture-spread" id="${x.id}" data-lecture-entry="${x.id}"><header><p class="eyebrow">${x.date} · ${x.label}</p><h2>${escapeHtml(x.title)}</h2><span class="lecture-source">Original note source: ${escapeHtml(x.source)}${matched.length?` · Slides ${matched[0].number}–${matched.at(-1).number}`:""}</span></header><div class="aligned-lecture-units">${freeNotes}${units}${extra}</div></section>`;
  }).join("");
  $$('[data-lecture-id]').forEach(b=>b.onclick=()=>$("#"+b.dataset.lectureId).scrollIntoView({behavior:"smooth",block:"start"}));
}
function updateLecturePosition(){const book=$("#lectureBook"),notes=lectureArchiveData.notes;if(!book||!notes.length)return;const marker=book.getBoundingClientRect().top+100;let current=notes[0].id;$$('[data-lecture-entry]').forEach(el=>{if(el.getBoundingClientRect().top<=marker)current=el.id});$$('[data-lecture-id]').forEach(b=>b.classList.toggle("active",b.dataset.lectureId===current));}
function renderSyllabus(){
  $("#syllabus-overview").innerHTML=`<p class="eyebrow">PDF PAGES 1–2</p><h2>Course purpose and structure</h2><p><span class="syllabus-highlight">Introduction to Group Dynamics meets Tuesday and Thursday, 3:30–4:45 p.m., from September 3 through December 15, 2026.</span></p><p>The course combines social, clinical, and political psychology with sociology and economics. Its goals include distinguishing group content from process, analyzing participation, applying group theory to everyday experience, and understanding how race, class, gender, sexuality, and nation shape group formation.</p><h3>How to succeed</h3><p><span class="syllabus-highlight">Complete readings before class, submit assignments on time, and participate actively.</span> Lecture, discussion, small-group activity, and individual work complement one another.</p>`;
  $("#syllabus-grades").innerHTML=`<p class="eyebrow">PDF PAGES 2 AND 5</p><h2>Assessment priorities</h2><div class="grade-grid"><div><b>60%</b><small>Three take-home exams</small></div><div><b>20%</b><small>Two reading responses</small></div><div><b>10%</b><small>Oral presentation</small></div><div><b>10%</b><small>Participation</small></div></div><p><span class="syllabus-critical">Take-home exams must reference lectures, readings, and discussion, include outside research, run roughly two to three single-spaced pages per answer, and include references.</span></p><p><span class="syllabus-highlight">Reading responses run two to four pages and must critically evaluate a selected reading, assess its arguments, and apply it to a real-world experience.</span> Proficient work uses three textual examples; exceptional work uses more than three.</p><p>The oral presentation requires an agreed topic, an outline, and at least three references posted on the presentation day.</p>`;
  $("#syllabus-policies").innerHTML=`<p class="eyebrow">PDF PAGE 3</p><h2>Policies to remember</h2><ul><li><span class="syllabus-critical">Two absences or four late arrivals/early departures lower the final grade by one letter step.</span></li><li>All submitted work must be in your own words and submitted individually unless the instructor says otherwise.</li><li>Students are responsible for lecture material, readings, and assignments.</li><li>The syllabus states that late online work loses one point per day up to five points. A later policy paragraph says late journals are not accepted and papers lose five points per day, so confirm which rule applies to each assignment.</li><li>Academic integrity and respectful participation are required.</li></ul>`;
  $("#syllabus-timeline").innerHTML=`<p class="eyebrow">PDF PAGES 3–4</p><h2>Fall 2026 timeline</h2><ol class="course-timeline">${courseTimeline.map(x=>`<li class="${x[3]||""}"><time>${x[0]}</time><b>${x[1]}</b><span>${x[2]}</span></li>`).join("")}</ol>`;
  $("#syllabus-readings").innerHTML=`<p class="eyebrow">PDF PAGES 5–6</p><h2>Required readings</h2><ul class="reading-list">${requiredReadings.map(x=>`<li>${x}</li>`).join("")}</ul><p class="source-note">This view is a study-oriented transcription of the supplied seven-page syllabus. Open the original PDF for the complete wording, APA details, university resources, and participation self-assessment.</p>`;
}
