function hideSelectionTools(){ $("#selectionTools")?.classList.remove("visible");editingAnnotationId="";$("#deleteAnnotation").hidden=true; }
function showAnnotationTools(mark){editingAnnotationId=mark.dataset.ann;const rect=mark.getBoundingClientRect(),tools=$("#selectionTools"),x=Math.max(190,Math.min(innerWidth-190,rect.left+Math.min(rect.width,280)/2));tools.style.left=x+"px";tools.style.top=(rect.top>90?rect.top-10:rect.bottom+10)+"px";tools.style.transform=rect.top>90?"translate(-50%,-100%)":"translate(-50%,0)";$("#deleteAnnotation").hidden=false;tools.classList.add("visible");}
function showSelectionTools(){
  const sel=window.getSelection();
  if(!sel || sel.isCollapsed || !sel.rangeCount)return hideSelectionTools();
  const range=sel.getRangeAt(0), container=range.commonAncestorContainer.nodeType===3?range.commonAncestorContainer.parentElement:range.commonAncestorContainer;
  if(!container?.closest?.("#documentText"))return hideSelectionTools();
  const rect=range.getBoundingClientRect(), tools=$("#selectionTools");
  const x=Math.max(190,Math.min(innerWidth-190,rect.left+rect.width/2));
  tools.style.left=x+"px";
  if(rect.top>90){tools.style.top=(rect.top-10)+"px";tools.style.transform="translate(-50%,-100%)";}
  else{tools.style.top=(rect.bottom+10)+"px";tools.style.transform="translate(-50%,0)";}
  tools.classList.add("visible");
}

