// Public showcase safeguard: keep all rendered interface and imported local content English-only.
const publicEnglishReplacements=new Map([
  ["关闭文内辅助","Close Inline Guide"],["文内辅助","Inline Guide"],["剩余","Remaining"],["页","pages"],
  ["已到末页","End of reading"],["条笔记","notes"],["书签","Bookmark"],["删除","Delete"],
  ["标注","Annotation"],["写下你的想法、问题或联系…","Add a thought, question, or connection…"],
  ["全部","All"],["查看答案","Reveal Answer"],["提交答案","Submit Answer"]
]);
function enforcePublicEnglish(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{let value=node.nodeValue;for(const [from,to] of publicEnglishReplacements)value=value.split(from).join(to);if(/[\u3400-\u9fff\uf900-\ufaff]/.test(value))value=value.replace(/[\u3400-\u9fff\uf900-\ufaff]/g,"").replace(/[：；，。！？【】（）《》、]/g," ").replace(/\s{2,}/g," ");node.nodeValue=value;});
}
enforcePublicEnglish();
new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1)enforcePublicEnglish(node);else if(node.nodeType===3&&/[\u3400-\u9fff\uf900-\ufaff]/.test(node.nodeValue))node.nodeValue=node.nodeValue.replace(/[\u3400-\u9fff\uf900-\ufaff]/g,"");}))).observe(document.body,{subtree:true,childList:true});
